import 'package:flutter/material.dart';

import 'energy_data.dart';

/// Represents an actionable smart recommendation generated by PANS ENERGI.
class EnergyRecommendation {
  final String id;
  final String title;
  final String summary;
  final String triggerCondition;
  final String suggestedAction;
  final String impactEstimated;
  final EnergyStatus applicableStatus;
  final IconData icon;
  final bool isAccepted;
  final String priority; // 'URGENT', 'HIGH', 'RECOMMENDED', 'MODERATE'

  const EnergyRecommendation({
    required this.id,
    required this.title,
    required this.summary,
    required this.triggerCondition,
    required this.suggestedAction,
    required this.impactEstimated,
    required this.applicableStatus,
    required this.icon,
    this.isAccepted = false,
    this.priority = 'RECOMMENDED',
  });

  EnergyRecommendation copyWith({
    String? id,
    String? title,
    String? summary,
    String? triggerCondition,
    String? suggestedAction,
    String? impactEstimated,
    EnergyStatus? applicableStatus,
    IconData? icon,
    bool? isAccepted,
    String? priority,
  }) {
    return EnergyRecommendation(
      id: id ?? this.id,
      title: title ?? this.title,
      summary: summary ?? this.summary,
      triggerCondition: triggerCondition ?? this.triggerCondition,
      suggestedAction: suggestedAction ?? this.suggestedAction,
      impactEstimated: impactEstimated ?? this.impactEstimated,
      applicableStatus: applicableStatus ?? this.applicableStatus,
      icon: icon ?? this.icon,
      isAccepted: isAccepted ?? this.isAccepted,
      priority: priority ?? this.priority,
    );
  }
}
